(7643450, 1241995, 5628, '<td valign="top">I like this image. Probably one of the best in this challenge. I believe the image could have benefited from a slightly deeper DOF.</td>', 'I like this image. Probably one of the best in this challenge. I believe the image could have benefited from a slightly deeper DOF.', '2019-10-11 01:32:17.000000', NULL, 1),
(7643451, 1241854, 5628, '<td valign="top">I like this image, but it doesnt fit the definition of abstract in my opinion. While the scene does feel surreal, you have a very definite real-world object here.</td>', 'I like this image, but it doesnt fit the definition of abstract in my opinion. While the scene does feel surreal, you have a very definite real-world object here.', '2019-10-11 01:38:14.000000', NULL, 1),
(7643452, 1242027, 5628, '<td valign="top">This is an interesting subject, but I think it would have worked better with more DOF. As-is, I cant quite tell where the focal point is.</td>', 'This is an interesting subject, but I think it would have worked better with more DOF. As-is, I cant quite tell where the focal point is.', '2019-10-11 01:40:36.000000', NULL, 1),
(7643453, 1241870, 5628, '<td valign="top">This is one of the few real abstract shots in the challenge this week. My only gripe is that there is a strange aberration on some of the lines which detracts from the effect.</td>', 'This is one of the few real abstract shots in the challenge this week. My only gripe is that there is a strange aberration on some of the lines which detracts from the effect.', '2019-10-11 01:46:27.000000', NULL, 1),
