(7644158, 1242010, 80096, '<td valign="top">The problem I have with this is it''s too recognizable which merely makes it a macro image, not an abstract.</td>', 'The problem I have with this is it''s too recognizable which merely makes it a macro image, not an abstract.', '2019-10-21 13:45:21.000000', NULL, 0),
(7644165, 1241963, 80096, '<td valign="top">Agree with Mariuca.. this is a true abstract however, the consistency and lack of contrast diminish the image''s appeal. Even an abstract needs a focal point especially black &amp; white where the lack of color makes it more difficult to create impact.</td>', 'Agree with Mariuca.. this is a true abstract however, the consistency and lack of contrast diminish the image''s appeal. Even an abstract needs a focal point especially black & white where the lack of color makes it more difficult to create impact.', '2019-10-21 14:00:35.000000', NULL, 0),
(7644168, 1241995, 80096, '<td valign="top">Hi Nikki - this is more of a macro image than an abstract. I''m surprised how many people interpreted this as a black &amp; white macro challenge. Perhaps we should schedule one of those next. ;-)</td>', 'Hi Nikki - this is more of a macro image than an abstract. I''m surprised how many people interpreted this as a black & white macro challenge. Perhaps we should schedule one of those next. ;-)', '2019-10-21 14:03:59.000000', NULL, 0),
(7644173, 1241910, 80096, '<td valign="top">A lack of continuity makes this less appealing.. too much empty black space. More existing texture would have tied this together nicely.</td>', 'A lack of continuity makes this less appealing.. too much empty black space. More existing texture would have tied this together nicely.', '2019-10-21 14:12:51.000000', NULL, 0),
